content.text:
#!/usr/bin/env dart

// Generates site/install.sh and site/install.ps1 from site/install-config.yaml.
//
// Usage:
//   dart run scripts/gen_installers.dart
//
// After editing site/install-config.yaml, rerun this script and commit the
// generated installer files. Do not edit install.sh / install.ps1 by hand.

import 'dart:io';

import 'package:yaml/yaml.dart';

const _configPath = 'site/install-config.yaml';
const _shTemplatePath = 'site/install.sh.template';
const _psTemplatePath = 'site/install.ps1.template';
const _batTemplatePath = 'site/install.bat.template';
const _shOut = 'site/install.sh';
const _psOut = 'site/install.ps1';
const _batOut = 'site/install.bat';
const _shSetupTemplatePath = 'site/setup.sh.template';
const _psSetupTemplatePath = 'site/setup.ps1.template';
const _shSetupOut = 'site/setup.sh';
const _psSetupOut = 'site/setup.ps1';

final _generatedHeader =
    '''
# ═══════════════════════════════════════════════════════════════════════════
#  DO NOT EDIT THIS FILE BY HAND. It is generated from site/install-config.yaml
#  by `dart run scripts/gen_installers.dart`.
# ═══════════════════════════════════════════════════════════════════════════
'''
        .trim();

void main() {
  final config = loadYaml(File(_configPath).readAsStringSync()) as YamlMap;
  final providers = config['providers'] as YamlList;
  final modes = config['modes'] as YamlList;
  final approvalModes = config['approval_modes'] as YamlList;
  final installConfig = config['install'] as YamlMap;

  final shBanner = _shBanner(installConfig);
  final psBanner = _psBanner(installConfig);
  final shRecipe = _shSetupRecipe(installConfig);
  final psRecipe = _psSetupRecipe(installConfig);

  // SEC-07 (#795): the default install pins a known version. Must be set in
  // install-config.yaml (a release that exists AND carries signed
  // provenance) — the pubspec version is NOT usable here: at generation
  // time that version usually has no release yet.
  final pinnedVersion = installConfig['pinned_cli_version'] as String? ?? '';
  if (pinnedVersion.isEmpty) {
    throw StateError(
      'install.pinned_cli_version is not set in $_configPath — install.sh '
      'must default to a pinned, provenance-carrying release (SEC-07 #795)',
    );
  }

  final sh = File(_shTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', shBanner)
      .replaceFirst('{{PINNED_VERSION}}', pinnedVersion)
      .replaceFirst('{{SETUP_RECIPE}}', shRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final ps = File(_psTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', psBanner)
      .replaceFirst('{{SETUP_RECIPE}}', psRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  final bat = File(_batTemplatePath).readAsStringSync().replaceFirst(
    ':: {{GENERATED_HEADER}}',
    _generatedHeader.replaceAll('# ', ':: '),
  );

  File(_shOut).writeAsStringSync(sh);
  // Windows PowerShell 5.1 parses scripts WITHOUT a BOM in the system ANSI
  // code page, which mojibakes the UTF-8 banner/glyphs at parse time (the
  // OutputEncoding line cannot fix already-corrupted literals). Writing the
  // BOM makes PS 5.1 read the file as UTF-8.
  File(_psOut).writeAsStringSync('\uFEFF$ps');
  File(_batOut).writeAsStringSync(bat);

  final shSetup = File(_shSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final psSetup = File(_psSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  File(_shSetupOut).writeAsStringSync(shSetup);
  // Same UTF-8 BOM rationale as install.ps1 (see above).
  File(_psSetupOut).writeAsStringSync('\uFEFF$psSetup');

  print(
    'Generated $_shOut, $_psOut, $_shSetupOut and $_psSetupOut from $_configPath',
  );
}

// ── Shell fragments ─────────────────────────────────────────────────────────

String _shProviderMenu(YamlList providers) {
  final b = StringBuffer();
  b.writeln(r'# Provider menu');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    final note = p['note'] ?? '';
    final rec = p['recommended'] == true ? '   (recommended)' : '';
    b.writeln('say "  ${i + 1}) ${p['name']}  — $note$rec"');
  }
  b.writeln(r'say ""');
  b.writeln(r'provider_choice=""');
  b.writeln(r'while true; do');
  b.write(r'  ask provider_choice "Pick a provider [1-');
  b.write(providers.length);
  b.writeln(r']" "1"');
  b.writeln(r'  case "$provider_choice" in');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    b.writeln(
      '    ${i + 1}|${p['id']}) provider="${p['id']}"; provider_kind="${p['kind']}"; break ;;',
    );
  }
  b.write(r'    *) warn "enter 1-');
  b.write(providers.length);
  b.writeln(r'" ;;');
  b.writeln(r'  esac');
  b.writeln(r'done');
  return b.toString();
}

String _shProviderCases(YamlList providers) {
